export class EventStream {
  constructor(prefix) {
    this.prefix = prefix;
    /** @type {((value: { value: string | undefined, done: boolean }) => void)[]} */
    this.waiting = [];
    /** @type {{ settled: boolean, resolve: ((value: string | undefined) => void) | undefined }[]} */
    this.pending = [];
  }

  render(value) {
    return this.prefix + value;
  }

  /** @returns {AsyncGenerator<string, number, undefined>} */
  async *[Symbol.asyncIterator]() {
    try {
      yield this.render("open");
      await new Promise((resolve) => setTimeout(resolve, 1));
      yield this.render("later");
      return 17;
    } finally {
      console.log(this.render("closed"));
    }
  }

  exerciseShift() {
    this.waiting.push((result) => console.log(`${result.done}:${result.value ?? "end"}`));
    const waiter = this.waiting.shift();
    if (waiter) waiter({ value: "event", done: false });
    console.log(this.waiting.shift() === undefined);

    this.pending.push({
      settled: false,
      resolve: (value) => console.log(value ?? "missing"),
    });
    const query = this.pending.shift();
    if (query && !query.settled) {
      query.settled = true;
      query.resolve?.("rgb");
    }
    console.log(this.pending.shift() === undefined);
  }

  /** @returns {AsyncIterable<string, number, undefined>} */
  asIterable() {
    return this;
  }

  /** @returns {Promise<void>} */
  async consume() {
    /** @type {AsyncGenerator<string, number, undefined>} */
    const direct = this[Symbol.asyncIterator]();
    console.log((await direct.next()).value);
    console.log((await direct.return(99)).value);

    for await (const value of this.asIterable()) {
      console.log(value);
      break;
    }

    /** @type {AsyncGenerator<string, number, undefined>} */
    const thrown = this[Symbol.asyncIterator]();
    console.log((await thrown.next()).value);
    try {
      await thrown.throw(new Error("stop"));
    } catch (e) {
      if (e instanceof Error) console.log(e.message);
    }
  }
}
